const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate polygon for the Flint Hills region in eastern Kansas
  const geometry = ee.Geometry.Polygon(
    [[[-97.0, 39.5],
      [-97.0, 37.5],
      [-95.5, 37.5],
      [-95.5, 39.5]]]);

  const date1_start = '2023-03-15';
  const date1_end = '2023-03-23'; // Around March 19, 2023

  const date2_start = '2023-04-04';
  const date2_end = '2023-04-12'; // Around April 8, 2023

  const NBR_BURN_THRESHOLD = 0.15; // NBR values below this are considered burned
  const SCALE = 100; // Sentinel-2 resolution is 10m, calculate at 100m for faster processing
  const AREA_UNIT_FACTOR = (SCALE / 1000) * (SCALE / 1000); // Converts pixel count to km^2

  // Function to mask clouds in Sentinel-2 surface reflectance data.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B8', 'B12', 'B11']) // Select NIR, SWIR2 for NBR, SWIR1 for cloud score if needed
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NBR
  function calculateNBR(image) {
    // NBR = (NIR - SWIR2) / (NIR + SWIR2)
    return image.normalizedDifference(['B8', 'B12']).rename('NBR');
  }

  // Function to process a single period
  async function processPeriod(start_date, end_date, geom, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geom)
      .filterDate(start_date, end_date)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    const colSize = await collection.size().getInfo();
    if (colSize === 0) {
      console.log(`No Sentinel-2 images found for ${periodName} (Date: ${start_date} to ${end_date}).`);
      return { area: null, count: 0, cloud_percentage: null, image_count: 0 };
    }

    // Apply cloud mask and calculate NBR
    let img = collection.map(maskS2clouds).median().clip(geom);

    // Check if the median image is null (e.g., all pixels masked out)
    const bandNames = await img.bandNames().getInfo();
    if (bandNames.length === 0) {
        console.log(`No valid pixels remain for ${periodName} after cloud masking.`);
        return { area: null, count: 0, cloud_percentage: null, image_count: colSize };
    }

    const nbr = calculateNBR(img);

    // Identify burned areas (NBR below threshold)
    const burned = nbr.lt(NBR_BURN_THRESHOLD).rename('burned');

    // Count valid pixels before thresholding (for NBR band)
    const nbrValidPixelCount = await nbr.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: SCALE,
      maxPixels: 1e9
    }).get('NBR').getInfo();

    if (nbrValidPixelCount === 0) {
      console.log(`No valid NBR pixels found for ${periodName} after cloud masking.`);
      return { area: null, count: 0, cloud_percentage: null, image_count: colSize };
    }

    // Calculate sum of burned pixels
    const burnedPixelSum = await burned.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: SCALE,
      maxPixels: 1e9
    }).get('burned').getInfo();

    const burnedAreaKm2 = burnedPixelSum * AREA_UNIT_FACTOR;

    // Get cloud percentage for context, taking the mean of original images' cloudy pixel percentage
    const avgCloudyPixelPercentage = await collection.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo();

    return { area: burnedAreaKm2, count: burnedPixelSum, cloud_percentage: avgCloudyPixelPercentage, image_count: colSize };
  }

  console.log('--- Flint Hills Burn Scar Analysis ---');

  // Process Period 1 (March 19, 2023)
  const result1 = await processPeriod(date1_start, date1_end, geometry, 'March 19, 2023');
  console.log(`March 19, 2023 period (Images: ${result1.image_count}, Avg Cloud: ${result1.cloud_percentage !== null ? result1.cloud_percentage.toFixed(2) + '%' : 'N/A'})`);
  if (result1.area === null) {
    if (result1.image_count === 0) {
      console.log('C1'); // Empty Collection
      return;
    } else {
      console.log('C2'); // No Valid Pixels
      return;
    }
  }
  console.log(`Burned area (March 19, 2023): ${result1.area.toFixed(2)} km² (Burned Pixels: ${result1.count})`);

  // Process Period 2 (April 8, 2023)
  const result2 = await processPeriod(date2_start, date2_end, geometry, 'April 8, 2023');
  console.log(`April 8, 2023 period (Images: ${result2.image_count}, Avg Cloud: ${result2.cloud_percentage !== null ? result2.cloud_percentage.toFixed(2) + '%' : 'N/A'})`);
  if (result2.area === null) {
    if (result2.image_count === 0) {
      console.log('C1'); // Empty Collection
      return;
    } else {
      console.log('C2'); // No Valid Pixels
      return;
    }
  }
  console.log(`Burned area (April 8, 2023): ${result2.area.toFixed(2)} km² (Burned Pixels: ${result2.count})`);

  // 5. Validation & Final Answer
  if (result1.area === null || result2.area === null) {
    console.log('C3'); // Calculation Failure if for some reason area is null here
    return;
  }

  if (result2.area > result1.area) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
